50	 * @param props - useFieldArray props
51	 *
52	 * @returns methods - functions to manipulate with the Field Arrays (dynamic inputs) {@link UseFieldArrayReturn}
53	 *
54	 * @example
55	 * ```tsx
56	 * function App() {
57	 *   const { register, control, handleSubmit, reset, trigger, setError } = useForm({
58	 *     defaultValues: {
59	 *       test: []
60	 *     }
