71	 *       ))}
72	 *       <button type="button" onClick={() => append({ firstName: "bill" })}>
73	 *         append
74	 *       </button>
75	 *       <input type="submit" />
76	 *     </form>
77	 *   );
78	 * }
79	 * ```
