27	export default function getDirtyFields<T>(
28	  data: T,
29	  formValues: T,
30	  dirtyFieldsFromValues?: Record<
31	    Extract<keyof T, string>,
32	    ReturnType<typeof markFieldsDirty> | boolean
33	  >,
34	) {
35	  if (!dirtyFieldsFromValues) {
36	    dirtyFieldsFromValues = markFieldsDirty(formValues);
37	  }
38	
39	  for (const key in data) {
40	    const value = data[key];
41	
42	    if (isTraversable(value)) {
43	      if (isUndefined(formValues) || isPrimitive(dirtyFieldsFromValues[key])) {
44	        dirtyFieldsFromValues[key] = markFieldsDirty(
45	          value,
46	          Array.isArray(value) ? [] : {},
47	        );
48	      } else {
49	        getDirtyFields(
50	          value,
51	          isNullOrUndefined(formValues) ? {} : formValues[key],
52	          dirtyFieldsFromValues[key],
53	        );
54	      }
55	    } else {
56	      const formValue = formValues[key];
57	      dirtyFieldsFromValues[key] = !deepEqual(value, formValue);
58	    }
59	  }
60	
61	  return dirtyFieldsFromValues;
62	}
